import {spawnSync} from 'node:child_process';
for(const command of ['node','/bin/echo']) {
 const result=spawnSync(command,command==='node'?['-e','console.log("child-output")']:['child-output'],{encoding:'utf8'});
 console.log(JSON.stringify({command,status:result.status,errorCode:result.error?.code,stdout:result.stdout,stderr:result.stderr}));
}
